let calculator: ([Int], Int) -> Int? = totalMinutes(for:bufferMinutes:)
let check = calculator([25, 40], 10)

Функция — значение с типом входов и выхода. Значение по умолчанию работает при прямом вызове по имени, но у переменной-функции нужно передать оба аргумента.

func totalMinutes(for durations: [Int], bufferMinutes: Int = 0) -> Int {
    durations.reduce(0, +) + bufferMinutes
}
func add(_ amount: Int, to weekMinutes: inout Int) { weekMinutes += amount }
var weekMinutes = 0
add(totalMinutes(for: [25, 40]), to: &weekMinutes)

При вызове метка `for` обязательна, а `&` отмечает изменение weekMinutes. Сверь расчёт в Swift Playground.
